import { createWriteStream } from 'node:fs';
import { pipeline } from 'node:stream/promises';
import JSZip from 'jszip';

export interface ZipEntry {
  /** Always generated by TERO (never a user-supplied path), so no traversal is possible. */
  name: string;
  data: Buffer;
}

/** Write entries to a ZIP file on disk, streaming the compressed output. Images are stored, not re-deflated. */
export async function writeZip(outputPath: string, entries: ZipEntry[], compress = false): Promise<void> {
  const zip = new JSZip();
  for (const e of entries) {
    if (!/^[\w][\w .()-]{0,120}$/.test(e.name)) throw new Error(`unsafe zip entry name: ${e.name}`);
    zip.file(e.name, e.data, { binary: true });
  }
  const stream = zip.generateNodeStream({
    streamFiles: true,
    compression: compress ? 'DEFLATE' : 'STORE',
    compressionOptions: compress ? { level: 6 } : undefined,
  });
  await pipeline(stream, createWriteStream(outputPath, { flags: 'wx' }));
}

export function pad(n: number, width = 3): string {
  return String(n).padStart(width, '0');
}
